krpano.action:
set(layer[dir_card_1].bgborder, '0');
set(layer[dir_card_2].bgborder, '0');
set(layer[dir_card_3].bgborder, '0');
set(layer[dir_card_4].bgborder, '0');
set(layer[dir_card_5].bgborder, '0');
set(layer[dir_card_6].bgborder, '0');
if(xml.scene == 'scene_zkixgpxjsxucxflxcg', set(layer[dir_card_1].bgborder, '2 0xFFFFFF 0.95'); );
if(xml.scene == 'scene_yexwelwirbxy', set(layer[dir_card_2].bgborder, '2 0xFFFFFF 0.95'); );
if(xml.scene == 'scene_ajhywnakxxbt', set(layer[dir_card_3].bgborder, '2 0xFFFFFF 0.95'); );
if(xml.scene == 'scene_aqmxugwfqxbt', set(layer[dir_card_4].bgborder, '2 0xFFFFFF 0.95'); );
if(xml.scene == 'scene_yiryeebmwxen', set(layer[dir_card_5].bgborder, '2 0xFFFFFF 0.95'); );
if(xml.scene == 'scene_yiryeexwkxen', set(layer[dir_card_6].bgborder, '2 0xFFFFFF 0.95'); );

if(trans_busy == true, exit(); );
if(xml.scene == 'scene_zkixgpxjsxucxflxcg', exit(); );
loadscene(scene_zkixgpxjsxucxflxcg, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));

if(trans_busy == true, exit(); );
if(xml.scene == 'scene_yexwelwirbxy', exit(); );
loadscene(scene_yexwelwirbxy, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));

if(trans_busy == true, exit(); );
if(xml.scene == 'scene_ajhywnakxxbt', exit(); );
loadscene(scene_ajhywnakxxbt, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));

if(trans_busy == true, exit(); );
if(xml.scene == 'scene_aqmxugwfqxbt', exit(); );
loadscene(scene_aqmxugwfqxbt, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));

if(trans_busy == true, exit(); );
if(xml.scene == 'scene_yiryeebmwxen', exit(); );
if(device.mobile,
	loadscene(scene_yiryeebmwxen, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));
  ,
	if(xml.scene == 'scene_yiryeexwkxen',
		trans_start_wei_to_shou();
	  ,
		loadscene(scene_yiryeebmwxen, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));
	);
);

if(trans_busy == true, exit(); );
if(xml.scene == 'scene_yiryeexwkxen', exit(); );
if(device.mobile,
	loadscene(scene_yiryeexwkxen, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));
  ,
	if(xml.scene == 'scene_yiryeebmwxen',
		trans_start_shou_to_wei();
	  ,
		loadscene(scene_yiryeexwkxen, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));
	);
);

if(trans_busy == true, exit(); );
set(trans_busy, true);
set(trans_target, 'scene_yiryeexwkxen');
set(trans_reveal_fov, 75.76);
set(trans_default_fov, 120);
set(autorotate.enabled, false);
set(control.usercontrol, off);
stopdelayedcall(trans_unlock);
stopdelayedcall(trans_behind_load);
stopdelayedcall(trans_zoom_done);
stopdelayedcall(trans_settle_done);
stoptween(view.hlookat);
stoptween(view.vlookat);
stoptween(view.fov);
set(layer[trans_video_wei_shou].visible, false);
set(layer[trans_video_wei_shou].enabled, false);
set(layer[trans_video_shou_wei].visible, false);
set(layer[trans_video_shou_wei].enabled, false);
set(layer[trans_video_shou_wei].alpha, 0);

set(layer[trans_video_shou_wei].visible, true);
set(layer[trans_video_shou_wei].enabled, true);
layer[trans_video_shou_wei].seek(0);
layer[trans_video_shou_wei].play();
delayedcall(trans_unlock, 0.05,
	layer[trans_video_shou_wei].pause();
	layer[trans_video_shou_wei].seek(0);
	set(layer[trans_video_shou_wei].visible, false);
	set(layer[trans_video_shou_wei].enabled, false);
);
tween(view.hlookat, 0.0, 1.2, easeInOutQuad);
tween(view.vlookat, 0.0, 1.2, easeInOutQuad);
tween(view.fov, 84.63, 1.2, easeInOutQuad,
	delayedcall(trans_zoom_done, 0.05, trans_play_shou_wei(); );
);

if(trans_busy == true, exit(); );
set(trans_busy, true);
set(trans_target, 'scene_yiryeebmwxen');
set(trans_reveal_fov, 84.63);
set(trans_default_fov, 120);
set(autorotate.enabled, false);
set(control.usercontrol, off);
stopdelayedcall(trans_unlock);
stopdelayedcall(trans_behind_load);
stopdelayedcall(trans_zoom_done);
stopdelayedcall(trans_settle_done);
stoptween(view.hlookat);
stoptween(view.vlookat);
stoptween(view.fov);
set(layer[trans_video_shou_wei].visible, false);
set(layer[trans_video_shou_wei].enabled, false);
set(layer[trans_video_wei_shou].visible, false);
set(layer[trans_video_wei_shou].enabled, false);
set(layer[trans_video_wei_shou].alpha, 0);
set(layer[trans_video_wei_shou].visible, true);
set(layer[trans_video_wei_shou].enabled, true);
layer[trans_video_wei_shou].seek(0);
layer[trans_video_wei_shou].play();
delayedcall(trans_unlock, 0.05,
	layer[trans_video_wei_shou].pause();
	layer[trans_video_wei_shou].seek(0);
	set(layer[trans_video_wei_shou].visible, false);
	set(layer[trans_video_wei_shou].enabled, false);
);
tween(view.hlookat, 0.0, 1.2, easeInOutQuad);
tween(view.vlookat, 0.0, 1.2, easeInOutQuad);
tween(view.fov, 75.76, 1.2, easeInOutQuad,
	delayedcall(trans_zoom_done, 0.05, trans_play_wei_shou(); );
);

if(trans_busy != true, exit(); );
set(layer[trans_video_shou_wei].visible, true);
set(layer[trans_video_shou_wei].enabled, true);
set(layer[trans_video_shou_wei].alpha, 1.0);
set(layer[trans_video_shou_wei].zorder, 120);
layer[trans_video_shou_wei].seek(0);
layer[trans_video_shou_wei].play();
trans_show_skip();
stopdelayedcall(trans_behind_load);
delayedcall(trans_behind_load, 0.12, trans_load_behind_shou_wei(); );

if(trans_busy != true, exit(); );
set(layer[trans_video_wei_shou].visible, true);
set(layer[trans_video_wei_shou].enabled, true);
set(layer[trans_video_wei_shou].alpha, 1.0);
set(layer[trans_video_wei_shou].zorder, 120);
layer[trans_video_wei_shou].seek(0);
layer[trans_video_wei_shou].play();
trans_show_skip();
stopdelayedcall(trans_behind_load);
delayedcall(trans_behind_load, 0.12, trans_load_behind_wei_shou(); );

if(trans_busy != true, exit(); );
loadscene(scene_yiryeexwkxen, null, MERGE|NOPREVIEW, NOBLEND);

lookat(0.0, 0.0, get(trans_reveal_fov));
delayedcall(0.02, lookat(0.0, 0.0, get(trans_reveal_fov)); );
set(layer[trans_video_shou_wei].visible, true);
set(layer[trans_video_shou_wei].enabled, true);
set(layer[trans_video_shou_wei].alpha, 1.0);
set(layer[trans_video_shou_wei].zorder, 120);
trans_show_skip();
set(control.usercontrol, off);
set(autorotate.enabled, false);
hide_skin_controlbar();
if(layer[trans_video_shou_wei].ispaused, layer[trans_video_shou_wei].play(); );

if(trans_busy != true, exit(); );
loadscene(scene_yiryeebmwxen, null, MERGE|NOPREVIEW, NOBLEND);
lookat(0.0, 0.0, get(trans_reveal_fov));
delayedcall(0.02, lookat(0.0, 0.0, get(trans_reveal_fov)); );
set(layer[trans_video_wei_shou].visible, true);
set(layer[trans_video_wei_shou].enabled, true);
set(layer[trans_video_wei_shou].alpha, 1.0);
set(layer[trans_video_wei_shou].zorder, 120);
trans_show_skip();
set(control.usercontrol, off);
set(autorotate.enabled, false);
hide_skin_controlbar();
if(layer[trans_video_wei_shou].ispaused, layer[trans_video_wei_shou].play(); );

stopdelayedcall(trans_unlock);
stopdelayedcall(trans_behind_load);
stopdelayedcall(trans_zoom_done);
stopdelayedcall(trans_settle_done);
stoptween(view.hlookat);
stoptween(view.vlookat);
stoptween(view.fov);
layer[trans_video_shou_wei].pause();
layer[trans_video_wei_shou].pause();
set(layer[trans_video_shou_wei].visible, false);
set(layer[trans_video_shou_wei].enabled, false);
set(layer[trans_video_shou_wei].alpha, 0);
set(layer[trans_video_wei_shou].visible, false);
set(layer[trans_video_wei_shou].enabled, false);
set(layer[trans_video_wei_shou].alpha, 0);
trans_hide_skip();
if(xml.scene != get(trans_target),
	loadscene(get(trans_target), null, MERGE|NOPREVIEW, NOBLEND);
);

lookat(0.0, 0.0, get(trans_reveal_fov));
set(control.usercontrol, off);
set(autorotate.enabled, false);
hide_skin_controlbar();
dir_update_active();
tween(view.hlookat, 0.0, 2.0, easeOutQuad);
tween(view.vlookat, 0.0, 2.0, easeOutQuad);
tween(view.fov, get(trans_default_fov), 2.0, easeOutQuad,
	delayedcall(trans_settle_done, 0.05,
		set(control.usercontrol, all);
		set(autorotate.enabled, true);
		set(trans_busy, false);
		hide_skin_controlbar();
	);
);

stopdelayedcall(dir_hits_enable);
if(layer[dir_bar].state == 'opened',
	set(layer[dir_bar].state, 'closed');
	set(layer[dir_hit_1].enabled, false);
	set(layer[dir_hit_2].enabled, false);
	set(layer[dir_hit_3].enabled, false);
	set(layer[dir_hit_4].enabled, false);
	set(layer[dir_hit_5].enabled, false);
	set(layer[dir_hit_6].enabled, false);
	if(device.mobile,
		tween(layer[dir_bar].x, -512, 0.45, easeOutCubic);
	  ,
		tween(layer[dir_bar].x, -706, 0.45, easeOutCubic);
	);
	set(layer[dir_toggle_icon].url, 'skin/dir_chevron_right.png');
  ,
	set(layer[dir_bar].state, 'opened');
	tween(layer[dir_bar].x, 0, 0.45, easeOutCubic);
	set(layer[dir_toggle_icon].url, 'skin/dir_chevron_left.png');
	delayedcall(dir_hits_enable, 0.45,
		set(layer[dir_hit_1].enabled, true);
		set(layer[dir_hit_2].enabled, true);
		set(layer[dir_hit_3].enabled, true);
		set(layer[dir_hit_4].enabled, true);
		set(layer[dir_hit_5].enabled, true);
		set(layer[dir_hit_6].enabled, true);
	);
);

skin_hideskin(instant);
set(layer[skin_layer].visible, false);
set(layer[skin_layer].enabled, false);
set(layer[skin_btn_show].visible, false);
set(layer[skin_btn_show].enabled, false);
set(layer[skin_btn_prev_fs].visible, false);
set(layer[skin_btn_prev_fs].enabled, false);
set(layer[skin_btn_next_fs].visible, false);
set(layer[skin_btn_next_fs].enabled, false);
if(layer[webvr_enterbutton],
	set(layer[webvr_enterbutton].visible, false);
	set(layer[webvr_enterbutton].enabled, false);
);

if(device.fullscreensupport,
	switch(fullscreen);
  ,
	set(display.iphonefullscreen, 1);
);

if(fullscreen,
	set(layer[ui_btn_fs_label].html, '退出');
  ,
	set(layer[ui_btn_fs_label].html, '全屏');
);

if(intro_played == true, exit(); );
set(intro_played, true);
set(autorotate.enabled, false);
set(control.usercontrol, off);

set(intro_h, get(view.hlookat));
set(intro_v, get(view.vlookat));
set(intro_fov, get(view.fov));
set(intro_fovmax, get(view.fovmax));

set(view.fovmax, 170);
set(view.limitview, off);
set(view.architectural, 0.0);
set(view.pannini, 0.0);
lookat(get(intro_h), 90, 150, 1.0, 0, 0);

delayedcall(intro_expand, 0.5,
	tween(view.vlookat, get(intro_v), 3.0, easeOutQuad);
	tween(view.fov, get(intro_fov), 3.0, easeOutQuad);
	tween(view.distortion, 0.0, 3.0, easeOutQuad);
	delayedcall(intro_done, 3.0,
		set(view.fovmax, get(intro_fovmax));
		set(view.limitview, auto);
		set(control.usercontrol, all);
		set(autorotate.enabled, true);
		hide_skin_controlbar();
	);
);
